#include <iostream>
#include <string>
#include <string_view>
#include <iomanip>

// Demonstrating the pitfall of protected vs private encapsulation
class CommissionEmployeeProtected {
public:
    CommissionEmployeeProtected(std::string_view first, std::string_view last, double sales, double rate)
        : firstName(first), lastName(last), grossSales(sales >= 0.0 ? sales : 0.0), commissionRate(rate > 0.0 && rate < 1.0 ? rate : 0.0) {}

    double earnings() const { return grossSales * commissionRate; }

protected:
    // Problem: Derived classes can bypass validation
    std::string firstName;
    std::string lastName;
    double grossSales;
    double commissionRate;
};

class FlawedDerived : public CommissionEmployeeProtected {
public:
    FlawedDerived(std::string_view first, std::string_view last, double sales, double rate)
        : CommissionEmployeeProtected(first, last, sales, rate) {}

    void corruptState() {
        // Directly assigning invalid negative values because grossSales is protected
        grossSales = -5000.0;
    }

    void display() const {
        std::cout << "Flawed derived grossSales: " << grossSales << "\n";
    }
};

int main() {
    FlawedDerived emp("Bob", "Lewis", 5000.0, 0.04);
    emp.display();
    emp.corruptState(); // Corrupts invariant
    emp.display();
    return 0;
}

#include <iostream>
#include <string>
#include <string_view>
#include <stdexcept>
#include <iomanip>

class CommissionEmployee {
public:
    CommissionEmployee(std::string_view first, std::string_view last, std::string_view ssn,
                       double sales = 0.0, double rate = 0.0)
        : firstName(first), lastName(last), socialSecurityNumber(ssn) {
        setGrossSales(sales);
        setCommissionRate(rate);
    }

    void setFirstName(std::string_view first) { firstName = first; }
    std::string getFirstName() const { return firstName; }

    void setLastName(std::string_view last) { lastName = last; }
    std::string getLastName() const { return lastName; }

    void setSocialSecurityNumber(std::string_view ssn) { socialSecurityNumber = ssn; }
    std::string getSocialSecurityNumber() const { return socialSecurityNumber; }

    void setGrossSales(double sales) {
        if (sales >= 0.0) {
            grossSales = sales;
        } else {
            throw std::invalid_argument("Gross sales must be >= 0.0");
        }
    }
    double getGrossSales() const { return grossSales; }

    void setCommissionRate(double rate) {
        if (rate > 0.0 && rate < 1.0) {
            commissionRate = rate;
        } else {
            throw std::invalid_argument("Commission rate must be > 0.0 and < 1.0");
        }
    }
    double getCommissionRate() const { return commissionRate; }

    double earnings() const {
        return getCommissionRate() * getGrossSales();
    }

    void print() const {
        std::cout << "commission employee: " << getFirstName() << ' ' << getLastName()
                  << "\nsocial security number: " << getSocialSecurityNumber()
                  << "\ngross sales: " << getGrossSales()
                  << "\ncommission rate: " << getCommissionRate();
    }

private:
    std::string firstName;
    std::string lastName;
    std::string socialSecurityNumber;
    double grossSales{0.0};
    double commissionRate{0.0};
};

class BasePlusCommissionEmployee : public CommissionEmployee {
public:
    BasePlusCommissionEmployee(std::string_view first, std::string_view last, std::string_view ssn,
                               double sales, double rate, double salary)
        : CommissionEmployee(first, last, ssn, sales, rate) {
        setBaseSalary(salary);
    }

    void setBaseSalary(double salary) {
        if (salary >= 0.0) {
            baseSalary = salary;
        } else {
            throw std::invalid_argument("Salary must be >= 0.0");
        }
    }
    double getBaseSalary() const { return baseSalary; }

    double earnings() const {
        return getBaseSalary() + CommissionEmployee::earnings();
    }

    void print() const {
        std::cout << "base-salaried ";
        CommissionEmployee::print();
        std::cout << "\nbase salary: " << getBaseSalary();
    }

private:
    double baseSalary{0.0};
};

int main() {
    std::cout << std::fixed << std::setprecision(2);

    BasePlusCommissionEmployee employee("Bob", "Lewis", "333-33-3333", 5000.0, 0.04, 300.0);

    std::cout << "Employee information obtained by get functions:\n"
              << "\nFirst name is " << employee.getFirstName()
              << "\nLast name is " << employee.getLastName()
              << "\nSocial security number is " << employee.getSocialSecurityNumber()
              << "\nGross sales is " << employee.getGrossSales()
              << "\nCommission rate is " << employee.getCommissionRate()
              << "\nBase salary is " << employee.getBaseSalary() << "\n\n";

    employee.setBaseSalary(1000.00);

    std::cout << "Updated employee information output by print function:\n\n";
    employee.print();
    std::cout << "\n\nEmployee's earnings: $" << employee.earnings() << "\n";

    return 0;
}
